/* Snippet: PXpace site behaviour — generated by sitereal. */
/* PXpace mockup behaviour. Hooks are data-* attributes only (never styling classes);
   state is written as is-* classes / aria-* attributes. In Bricks: Settings › Custom code (body footer). */
(() => {
  const root = document.documentElement;
  root.classList.add('has-js');
  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* scroll reveal: [data-animate] gets .is-in once it enters the viewport */
  const io = new IntersectionObserver((entries) => entries.forEach((e) => {
    if (e.isIntersecting) { e.target.classList.add('is-in'); io.unobserve(e.target); }
  }), { threshold: 0.15 });
  document.querySelectorAll('[data-animate]').forEach((el) => io.observe(el));

  /* marquee: duplicate the children once so translate(-50%) loops seamlessly */
  document.querySelectorAll('[data-marquee]').forEach((track) => {
    [...track.children].forEach((child) => {
      const copy = child.cloneNode(true);
      copy.setAttribute('aria-hidden', 'true');
      copy.removeAttribute('data-component');
      track.append(copy);
    });
  });

  /* switch (hero toggle): flips aria-checked and the active word of its group */
  document.querySelectorAll('[data-switch]').forEach((sw) => sw.addEventListener('click', () => {
    const on = sw.getAttribute('aria-checked') !== 'true';
    sw.setAttribute('aria-checked', String(on));
    const group = sw.closest('[data-switch-group]');
    if (!group) return;
    group.querySelectorAll('[data-switch-word]').forEach((w) => w.classList.toggle('is-active', (w.dataset.switchWord === 'on') === on));
  }));

  /* accordion: one item open; optional image swap on [data-accordion-target] inside the same section */
  document.querySelectorAll('[data-accordion]').forEach((acc) => {
    const target = acc.closest('section')?.querySelector('[data-accordion-target]');
    acc.querySelectorAll('[data-accordion-trigger]').forEach((btn) => btn.addEventListener('click', () => {
      const item = btn.closest('[data-accordion-item]');
      acc.querySelectorAll('[data-accordion-item]').forEach((i) => {
        const open = i === item;
        i.classList.toggle('is-open', open);
        i.querySelector('[data-accordion-trigger]').setAttribute('aria-expanded', String(open));
      });
      if (target && item.dataset.accordionImage) target.src = item.dataset.accordionImage;
    }));
  });

  /* mega menu: [data-mega-trigger="x"] toggles [data-mega="x"] */
  const closeMegas = () => document.querySelectorAll('[data-mega-trigger]').forEach((t) => {
    t.setAttribute('aria-expanded', 'false');
    document.querySelector(`[data-mega="${t.dataset.megaTrigger}"]`)?.classList.remove('is-open');
  });
  document.querySelectorAll('[data-mega-trigger]').forEach((t) => t.addEventListener('click', (e) => {
    e.stopPropagation();
    const open = t.getAttribute('aria-expanded') !== 'true';
    closeMegas();
    t.setAttribute('aria-expanded', String(open));
    document.querySelector(`[data-mega="${t.dataset.megaTrigger}"]`)?.classList.toggle('is-open', open);
  }));
  document.addEventListener('click', (e) => { if (!e.target.closest('[data-mega]')) closeMegas(); });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeMegas(); });

  /* light / dark switch: same storage key + attribute Bricks uses (localStorage "brx_mode", data-brx-theme) */
  document.querySelectorAll('[data-theme-toggle]').forEach((t) => t.addEventListener('click', () => {
    const next = root.getAttribute('data-brx-theme') === 'dark' ? 'light' : 'dark';
    root.setAttribute('data-brx-theme', next);
    localStorage.setItem('brx_mode', next);
    t.setAttribute('aria-pressed', String(next === 'dark'));
  }));

  /* footer "Load More" */
  document.querySelectorAll('[data-menu-more]').forEach((b) => b.addEventListener('click', () => {
    b.setAttribute('aria-expanded', String(b.getAttribute('aria-expanded') !== 'true'));
  }));

  /* per-character label swap: [data-split-chars="<char class>"] wraps every character of each child label in a
     span of that class with --i = its index (the CSS staggers on it), then marks the box .is-split. The link
     gets the plain text as aria-label so screen readers do not spell the label out. Without JS (and in the
     Bricks builder) the CSS falls back to the whole-label swap. */
  document.querySelectorAll('[data-split-chars]').forEach((box) => {
    const cls = box.dataset.splitChars;
    const control = box.closest('a, button');
    if (control && !control.hasAttribute('aria-label')) control.setAttribute('aria-label', box.firstElementChild.textContent.trim());
    [...box.children].forEach((label) => {
      const text = label.textContent.trim();
      label.textContent = '';
      [...text].forEach((ch, i) => {
        const span = document.createElement('span');
        span.className = cls;
        span.style.setProperty('--i', i);
        span.textContent = ch === ' ' ? '\u00A0' : ch;
        label.append(span);
      });
    });
    box.classList.add('is-split');
  });

  /* ---------- forms ----------
     [data-field] = one field (label + [data-field-control] + hint/error); [data-field-clear] empties its input,
     [data-reveal] shows / hides a password, [data-meter="<input id>"] rates it, [data-counter="<textarea id>"]
     counts against maxlength, [data-select] is a custom listbox, [data-datepicker] a calendar dialog,
     form[data-validate] checks every field on submit (data-demo: no request, shows the status instead).
     Validation rewards early and punishes late: a field is checked when it is left with a value, re-checked live
     while it is invalid, and every field at submit. Custom controls write a hidden input and validate on pick. */
  const fieldParts = (field) => {
    const custom = field.querySelector('[data-select], [data-datepicker]');
    return {
      custom, control: field.querySelector('[data-field-control]'),
      input: custom ? custom.querySelector('[data-select-input], [data-date-input]') : field.querySelector('input, textarea'),
      focusable: custom ? custom.querySelector('[data-select-trigger], [data-date-trigger]') : field.querySelector('input, textarea'),
    };
  };
  const validate = (field) => {
    const { custom, control, input, focusable } = fieldParts(field);
    const ok = custom ? !(custom.hasAttribute('data-required') && !input.value) : input.checkValidity();
    field.classList.toggle('is-invalid', !ok);
    control.classList.toggle('is-invalid', !ok);
    control.classList.toggle('is-valid', ok && input.value !== '' && !custom);
    focusable.setAttribute('aria-invalid', String(!ok));
    return ok;
  };
  const shake = (el) => { el.classList.remove('is-shake'); void el.offsetWidth; el.classList.add('is-shake'); };
  document.addEventListener('animationend', (e) => { if (e.animationName === 'w-shake') e.target.closest('.is-shake')?.classList.remove('is-shake'); });

  document.querySelectorAll('[data-field]').forEach((field) => {
    const { custom, control, input } = fieldParts(field);
    if (custom) return; // listbox / calendar validate when a value is picked
    input.addEventListener('blur', () => { if (input.value !== '' || field.classList.contains('is-invalid')) validate(field); });
    input.addEventListener('input', () => {
      if (field.classList.contains('is-invalid')) validate(field);
      else control.classList.remove('is-valid');
    });
    // the whole box is the hit area (padding, icon, affix), like a label
    control.addEventListener('mousedown', (e) => {
      if (!e.target.closest('button, input, textarea')) { e.preventDefault(); input.focus(); }
    });
  });

  document.querySelectorAll('[data-field-clear]').forEach((btn) => btn.addEventListener('click', () => {
    const input = btn.closest('[data-field-control]').querySelector('input, textarea');
    input.value = '';
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.focus();
  }));

  document.querySelectorAll('[data-reveal]').forEach((btn) => btn.addEventListener('click', () => {
    const input = btn.closest('[data-field-control]').querySelector('input');
    const show = input.type === 'password';
    input.type = show ? 'text' : 'password';
    btn.setAttribute('aria-pressed', String(show));
    btn.setAttribute('aria-label', show ? 'Hide password' : 'Show password');
    input.focus({ preventScroll: true });
    input.setSelectionRange(input.value.length, input.value.length);
  }));

  document.querySelectorAll('[data-meter]').forEach((meter) => {
    const input = document.getElementById(meter.dataset.meter);
    const label = meter.querySelector('[data-meter-label]');
    const hint = label.textContent;
    const words = meter.dataset.meterLabels.split('|');
    const levels = ['is-weak', 'is-fair', 'is-good', 'is-strong'];
    input.addEventListener('input', () => {
      const v = input.value;
      const points = (v.length >= 8) + (v.length >= 12) + (/[a-z]/.test(v) && /[A-Z]/.test(v)) + /\d/.test(v) + /[^A-Za-z0-9]/.test(v);
      const score = !v ? 0 : v.length < 8 ? 1 : Math.max(1, Math.min(4, points));
      levels.forEach((c, i) => meter.classList.toggle(c, i === score - 1));
      label.textContent = score ? words[score - 1] : hint;
    });
  });

  document.querySelectorAll('[data-counter]').forEach((counter) => {
    const input = document.getElementById(counter.dataset.counter);
    const max = input.maxLength;
    const update = () => {
      const n = input.value.length;
      counter.textContent = `${n} / ${max}`;
      counter.classList.toggle('is-near', n >= max * 0.9 && n < max);
      counter.classList.toggle('is-full', n >= max);
    };
    input.addEventListener('input', update);
    update();
  });
  /* textareas grow with their content: CSS field-sizing where supported, height from scrollHeight otherwise */
  if (!CSS.supports('field-sizing', 'content')) document.querySelectorAll('[data-autogrow]').forEach((ta) => {
    const fit = () => { ta.style.height = 'auto'; ta.style.height = `${ta.scrollHeight}px`; };
    ta.addEventListener('input', fit);
    fit();
  });

  /* listbox (ARIA "select-only combobox"; with [data-select-search] the search input owns the active option) */
  document.querySelectorAll('[data-select]').forEach((sel) => {
    const q = (hook) => sel.querySelector(`[data-select-${hook}]`);
    const trigger = q('trigger'), value = q('value'), input = q('input'), panel = q('panel'), list = q('list');
    const search = q('search'), empty = q('empty'), highlight = q('highlight');
    const options = [...sel.querySelectorAll('[data-select-option]')];
    const owner = search || list;
    const field = sel.closest('[data-field]');
    const labelOf = (o) => o.querySelector('[data-select-label]').textContent;
    const enabled = () => options.filter((o) => !o.hidden && o.getAttribute('aria-disabled') !== 'true');
    let active = null, typed = '', typedAt = 0;

    const setActive = (opt, scroll) => {
      active = opt;
      if (!opt) { highlight.classList.remove('is-visible'); owner.removeAttribute('aria-activedescendant'); return; }
      owner.setAttribute('aria-activedescendant', opt.id);
      const jump = !highlight.classList.contains('is-visible'); // first appearance: place, do not glide
      if (jump) highlight.style.transition = 'none';
      highlight.style.transform = `translateY(${list.offsetTop + opt.offsetTop}px)`;
      highlight.style.height = `${opt.offsetHeight}px`;
      if (jump) { void highlight.offsetWidth; highlight.style.transition = ''; }
      highlight.classList.add('is-visible');
      if (scroll) opt.scrollIntoView({ block: 'nearest' });
    };
    const filter = (text) => {
      const t = text.trim().toLowerCase();
      options.forEach((o) => { o.hidden = t !== '' && !o.textContent.toLowerCase().includes(t); });
      empty.hidden = options.some((o) => !o.hidden);
      setActive(enabled()[0] || null);
    };
    const open = () => {
      if (sel.classList.contains('is-open')) return;
      const r = trigger.getBoundingClientRect();
      const below = innerHeight - r.bottom;
      sel.classList.toggle('is-up', below < panel.offsetHeight + 16 && r.top > below);
      sel.classList.add('is-open');
      trigger.setAttribute('aria-expanded', 'true');
      if (search) { search.value = ''; filter(''); }
      owner.focus({ preventScroll: true });
      setActive(options.find((o) => o.getAttribute('aria-selected') === 'true') || enabled()[0], true);
    };
    const close = (refocus) => {
      if (!sel.classList.contains('is-open')) return;
      sel.classList.remove('is-open');
      trigger.setAttribute('aria-expanded', 'false');
      setActive(null);
      if (refocus) trigger.focus({ preventScroll: true });
    };
    const choose = (opt) => {
      options.forEach((o) => o.setAttribute('aria-selected', String(o === opt)));
      input.value = opt.dataset.value;
      value.textContent = labelOf(opt);
      value.classList.remove('is-placeholder', 'is-changed');
      void value.offsetWidth;
      value.classList.add('is-changed');
      input.dispatchEvent(new Event('change', { bubbles: true }));
      close(true);
      if (field) validate(field);
    };

    trigger.addEventListener('click', () => (sel.classList.contains('is-open') ? close(true) : open()));
    trigger.addEventListener('keydown', (e) => {
      if (['ArrowDown', 'ArrowUp', 'Enter', ' '].includes(e.key)) { e.preventDefault(); open(); }
    });
    search?.addEventListener('input', () => filter(search.value));
    panel.addEventListener('mousedown', (e) => { if (e.target !== search) e.preventDefault(); }); // keep focus inside
    panel.addEventListener('keydown', (e) => {
      const opts = enabled();
      const i = opts.indexOf(active);
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        e.preventDefault();
        const down = e.key === 'ArrowDown';
        setActive(i < 0 ? opts[down ? 0 : opts.length - 1] : opts[(i + (down ? 1 : -1) + opts.length) % opts.length], true);
      } else if ((e.key === 'Home' || e.key === 'End') && !search) {
        e.preventDefault();
        setActive(e.key === 'Home' ? opts[0] : opts[opts.length - 1], true);
      } else if (e.key === 'Enter' || (e.key === ' ' && !search && Date.now() - typedAt > 600)) { // a space mid-word types
        e.preventDefault();
        if (active) choose(active);
      } else if (e.key === 'Escape') {
        e.preventDefault();
        e.stopPropagation();
        close(true);
      } else if (e.key === 'Tab') {
        close(false);
      } else if (!search && e.key.length === 1) { // type-ahead
        if (e.key === ' ') e.preventDefault();
        const now = Date.now();
        typed = (now - typedAt > 600 ? '' : typed) + e.key.toLowerCase();
        typedAt = now;
        const hit = opts.find((o) => labelOf(o).toLowerCase().startsWith(typed));
        if (hit) setActive(hit, true);
      }
    });
    options.forEach((o) => {
      o.addEventListener('mousemove', () => { if (o !== active && o.getAttribute('aria-disabled') !== 'true') setActive(o); });
      o.addEventListener('click', () => { if (o.getAttribute('aria-disabled') !== 'true') choose(o); });
    });
    sel.addEventListener('focusout', (e) => { if (!sel.contains(e.relatedTarget)) close(false); });
  });

  /* date picker (ARIA date-picker dialog): 6-week grid, Monday first, roving tabindex. Arrows ±1 day / ±1 week,
     Home/End = week start/end, PageUp/PageDown = month (+ Shift = year), Enter/Space picks, Esc closes.
     data-min="today" (or an ISO date) disables earlier days; [data-date-preset="0|1|7|monday"] jumps and picks. */
  const DAY = 864e5;
  const lang = root.lang || 'en';
  const pad = (n) => String(n).padStart(2, '0');
  const iso = (d) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
  const fromIso = (s) => { const [y, m, d] = s.split('-').map(Number); return new Date(y, m - 1, d); };
  const addDays = (d, n) => new Date(d.getFullYear(), d.getMonth(), d.getDate() + n);
  const addMonths = (d, n) => { // keeps the day, clamped to the target month's length
    const t = new Date(d.getFullYear(), d.getMonth() + n, 1);
    return new Date(t.getFullYear(), t.getMonth(), Math.min(d.getDate(), new Date(t.getFullYear(), t.getMonth() + 1, 0).getDate()));
  };
  const fmtMonth = new Intl.DateTimeFormat(lang, { month: 'long', year: 'numeric' });
  const fmtLong = new Intl.DateTimeFormat(lang, { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
  const fmtShort = new Intl.DateTimeFormat(lang, { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' });
  const fmtRel = new Intl.RelativeTimeFormat(lang, { numeric: 'auto' });
  const relative = (d, today) => {
    const n = Math.round((d - today) / DAY);
    const t = Math.abs(n) < 14 ? fmtRel.format(n, 'day') : fmtRel.format(Math.round(n / 7), 'week');
    return t.charAt(0).toUpperCase() + t.slice(1);
  };

  document.querySelectorAll('[data-datepicker]').forEach((dp) => {
    const q = (hook) => dp.querySelector(`[data-date-${hook}]`);
    const trigger = q('trigger'), value = q('value'), rel = q('relative'), input = q('input'), panel = q('panel');
    const month = q('month'), prev = q('prev'), next = q('next'), days = q('days'), clear = q('clear');
    const field = dp.closest('[data-field]');
    const today = addDays(new Date(), 0);
    const min = dp.dataset.min === 'today' ? today : dp.dataset.min ? fromIso(dp.dataset.min) : null;
    const placeholder = value.textContent;
    const tooEarly = (d) => min !== null && d < min;
    let selected = input.value ? fromIso(input.value) : null;
    let view = new Date(today.getFullYear(), today.getMonth(), 1);
    let focusDate = today;

    const render = (dir) => {
      month.textContent = fmtMonth.format(view);
      const first = new Date(view.getFullYear(), view.getMonth(), 1);
      const start = addDays(first, -((first.getDay() + 6) % 7));
      const weeks = [];
      for (let w = 0; w < 6; w++) {
        const row = document.createElement('div');
        row.className = 'w-datepicker__week';
        row.setAttribute('role', 'row');
        for (let i = 0; i < 7; i++) {
          const d = addDays(start, w * 7 + i);
          const b = document.createElement('button');
          b.type = 'button';
          b.className = 'w-datepicker__day';
          b.setAttribute('role', 'gridcell');
          b.dataset.date = iso(d);
          b.textContent = d.getDate();
          b.setAttribute('aria-label', fmtLong.format(d));
          b.tabIndex = +d === +focusDate ? 0 : -1;
          b.classList.toggle('is-outside', d.getMonth() !== view.getMonth());
          if (+d === +today) { b.classList.add('is-today'); b.setAttribute('aria-current', 'date'); }
          if (selected && +d === +selected) { b.classList.add('is-selected'); b.setAttribute('aria-selected', 'true'); }
          if (tooEarly(d)) b.setAttribute('aria-disabled', 'true');
          row.append(b);
        }
        weeks.push(row);
      }
      days.replaceChildren(...weeks);
      prev.disabled = min !== null && new Date(view.getFullYear(), view.getMonth(), 0) < min;
      if (dir) [days, month].forEach((n) => { n.classList.remove('is-next', 'is-prev'); void n.offsetWidth; n.classList.add(dir); });
    };
    const dayButton = (d) => days.querySelector(`[data-date="${iso(d)}"]`);
    const moveTo = (d) => { // focus a date, switching months (with a slide) when it lies outside the view
      const target = new Date(d.getFullYear(), d.getMonth(), 1);
      const dir = target > view ? 'is-next' : target < view ? 'is-prev' : null;
      focusDate = d;
      view = target;
      render(dir);
      dayButton(d).focus({ preventScroll: true });
    };
    const show = () => {
      value.textContent = selected ? fmtShort.format(selected) : placeholder;
      value.classList.toggle('is-placeholder', !selected);
      rel.textContent = selected ? relative(selected, today) : '';
      input.value = selected ? iso(selected) : '';
      value.classList.remove('is-changed');
      void value.offsetWidth;
      value.classList.add('is-changed');
      input.dispatchEvent(new Event('change', { bubbles: true }));
      if (field) validate(field);
    };
    const open = () => {
      if (dp.classList.contains('is-open')) return;
      const r = trigger.getBoundingClientRect();
      const below = innerHeight - r.bottom;
      dp.classList.toggle('is-up', below < panel.offsetHeight + 16 && r.top > below);
      focusDate = selected || (min && today < min ? min : today);
      view = new Date(focusDate.getFullYear(), focusDate.getMonth(), 1);
      render(null);
      dp.classList.add('is-open');
      trigger.setAttribute('aria-expanded', 'true');
      dayButton(focusDate).focus({ preventScroll: true });
    };
    const close = (refocus) => {
      if (!dp.classList.contains('is-open')) return;
      dp.classList.remove('is-open');
      trigger.setAttribute('aria-expanded', 'false');
      if (refocus) trigger.focus({ preventScroll: true });
    };
    const pick = (d) => {
      if (tooEarly(d)) return;
      selected = d;
      moveTo(d);
      dayButton(d).classList.add('is-picked'); // pop, then close
      show();
      setTimeout(() => close(true), 220);
    };

    trigger.addEventListener('click', () => (dp.classList.contains('is-open') ? close(true) : open()));
    trigger.addEventListener('keydown', (e) => { if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); open(); } });
    prev.addEventListener('click', () => moveTo(addMonths(focusDate, -1)));
    next.addEventListener('click', () => moveTo(addMonths(focusDate, 1)));
    days.addEventListener('click', (e) => { const b = e.target.closest('[data-date]'); if (b) pick(fromIso(b.dataset.date)); });
    days.addEventListener('keydown', (e) => {
      const b = e.target.closest('[data-date]');
      if (!b) return;
      const d = fromIso(b.dataset.date);
      const wd = (d.getDay() + 6) % 7;
      const to = {
        ArrowLeft: () => addDays(d, -1), ArrowRight: () => addDays(d, 1), ArrowUp: () => addDays(d, -7), ArrowDown: () => addDays(d, 7),
        Home: () => addDays(d, -wd), End: () => addDays(d, 6 - wd),
        PageUp: () => addMonths(d, e.shiftKey ? -12 : -1), PageDown: () => addMonths(d, e.shiftKey ? 12 : 1),
      }[e.key];
      if (to) { e.preventDefault(); moveTo(to()); }
    });
    dp.querySelectorAll('[data-date-preset]').forEach((p) => p.addEventListener('click', () => {
      const v = p.dataset.datePreset;
      pick(v === 'monday' ? addDays(today, ((8 - today.getDay()) % 7) || 7) : addDays(today, Number(v)));
    }));
    clear.addEventListener('click', () => { selected = null; render(null); show(); close(true); });
    panel.addEventListener('keydown', (e) => { if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); close(true); } });
    dp.addEventListener('focusout', (e) => { if (e.relatedTarget && !dp.contains(e.relatedTarget)) close(false); });
    document.addEventListener('mousedown', (e) => { if (!dp.contains(e.target)) close(false); });
    if (selected) show();
  });

  document.querySelectorAll('form[data-validate]').forEach((form) => {
    form.noValidate = true;
    form.addEventListener('input', () => form.classList.remove('is-sent'));
    form.addEventListener('submit', (e) => {
      const bad = [...form.querySelectorAll('[data-field]')].filter((f) => !validate(f));
      if (bad.length) {
        e.preventDefault();
        form.classList.remove('is-sent');
        bad.forEach((f) => shake(fieldParts(f).control));
        fieldParts(bad[0]).focusable.focus();
        return;
      }
      if (form.hasAttribute('data-demo')) { e.preventDefault(); form.classList.add('is-sent'); }
    });
  });

  /* glyph matrix: canvas of flickering monospace glyphs over the sky photos (colour from --glyph-color) */
  const GLYPHS = '01<>/{}[]=+*#$%&xX'.split('');
  document.querySelectorAll('[data-glyph-matrix]').forEach((host) => {
    const canvas = document.createElement('canvas');
    host.append(canvas);
    const ctx = canvas.getContext('2d');
    const rgb = getComputedStyle(host).getPropertyValue('--glyph-color').trim();
    const dpr = Math.min(devicePixelRatio || 1, 2);
    const S = 11;
    let w = 0, h = 0, cols = 0, cells = [];
    const pick = () => GLYPHS[(Math.random() * GLYPHS.length) | 0];
    const alpha = () => (Math.random() < 0.55 ? Math.random() * 0.38 : 0);
    const size = () => {
      w = host.clientWidth; h = host.clientHeight;
      canvas.width = w * dpr; canvas.height = h * dpr; ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      cols = Math.ceil(w / S);
      cells = Array.from({ length: cols * Math.ceil(h / S) }, () => ({ g: pick(), a: alpha() }));
    };
    const draw = () => {
      ctx.clearRect(0, 0, w, h);
      ctx.font = '9px "Geist Mono", monospace'; ctx.textBaseline = 'top';
      cells.forEach((c, i) => {
        if (c.a < 0.03) return;
        ctx.fillStyle = `rgba(${rgb}, ${c.a})`;
        ctx.fillText(c.g, (i % cols) * S, ((i / cols) | 0) * S);
      });
    };
    size(); draw();
    new ResizeObserver(() => { size(); draw(); }).observe(host);
    if (!reduceMotion) setInterval(() => {
      for (let k = 0; k < cells.length * 0.02; k++) { const c = cells[(Math.random() * cells.length) | 0]; c.g = pick(); c.a = alpha(); }
      draw();
    }, 120);
  });

  /* ---------- docs (docs.html, docs-article.html) ---------- */
  const copyText = async (text) => {
    try { await navigator.clipboard.writeText(text); return true; } catch {
      const ta = document.createElement('textarea');
      ta.value = text; ta.setAttribute('readonly', ''); ta.style.cssText = 'position:fixed;opacity:0';
      document.body.append(ta); ta.select();
      const ok = document.execCommand('copy'); ta.remove(); return ok;
    }
  };
  const flash = (el) => { el.classList.add('is-copied'); setTimeout(() => el.classList.remove('is-copied'), 1600); };
  const pageUrl = location.href.split('#')[0];

  /* shortcut hint follows the platform: ⌘K on Apple, Ctrl K elsewhere */
  if (!/Mac|iPhone|iPad/.test(navigator.platform)) document.querySelectorAll('[data-docs-search-key]').forEach((k) => { k.textContent = 'Ctrl K'; });

  /* search dialog: [data-docs-search-open] / ⌘K / Ctrl K / "/" open it; typing filters the hits (mockup data);
     ↑ ↓ move .is-selected, Enter opens, Esc or a click on the backdrop closes and returns focus */
  const searchDialog = document.querySelector('[data-docs-search-dialog]');
  if (searchDialog) {
    const input = searchDialog.querySelector('[data-docs-search-input]');
    const hits = [...searchDialog.querySelectorAll('[data-docs-search-hit]')];
    const empty = searchDialog.querySelector('[data-docs-search-empty]');
    const query = searchDialog.querySelector('[data-docs-search-query]');
    let lastFocus = null;
    let sel = 0;
    const visible = () => hits.filter((h) => !h.parentElement.hidden);
    const select = (i) => {
      const v = visible();
      sel = Math.max(0, Math.min(i, v.length - 1));
      hits.forEach((h) => h.classList.toggle('is-selected', h === v[sel]));
      v[sel]?.scrollIntoView({ block: 'nearest' });
    };
    const filter = () => {
      const q = input.value.trim().toLowerCase();
      hits.forEach((h) => { h.parentElement.hidden = Boolean(q) && !h.textContent.toLowerCase().includes(q); });
      empty.hidden = visible().length > 0;
      query.textContent = input.value.trim();
      select(0);
    };
    const isOpen = () => searchDialog.classList.contains('is-open');
    const open = () => {
      lastFocus = document.activeElement;
      searchDialog.classList.add('is-open'); searchDialog.setAttribute('aria-hidden', 'false');
      input.value = ''; filter();
      setTimeout(() => input.focus(), 30);
    };
    const close = () => {
      searchDialog.classList.remove('is-open'); searchDialog.setAttribute('aria-hidden', 'true');
      lastFocus?.focus?.();
    };
    document.querySelectorAll('[data-docs-search-open]').forEach((b) => b.addEventListener('click', open));
    searchDialog.querySelectorAll('[data-docs-search-close]').forEach((b) => b.addEventListener('click', close));
    searchDialog.addEventListener('click', (e) => { if (e.target === searchDialog) close(); });
    input.addEventListener('input', filter);
    hits.forEach((h) => h.addEventListener('mousemove', () => select(visible().indexOf(h))));
    document.addEventListener('keydown', (e) => {
      if (e.key.toLowerCase() === 'k' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); if (isOpen()) close(); else open(); return; }
      if (e.key === '/' && !isOpen() && !/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement.tagName)) { e.preventDefault(); open(); return; }
      if (!isOpen()) return;
      if (e.key === 'Escape') { e.preventDefault(); close(); }
      else if (e.key === 'ArrowDown') { e.preventDefault(); select(sel + 1); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); select(sel - 1); }
      else if (e.key === 'Enter' && visible()[sel]) { e.preventDefault(); visible()[sel].click(); }
    });
  }

  /* sidebar drawer below 992 px: [data-docs-drawer-open] → [data-docs-drawer].is-open; closes on outside click / Esc */
  const drawer = document.querySelector('[data-docs-drawer]');
  if (drawer) {
    const setDrawer = (open) => {
      drawer.classList.toggle('is-open', open);
      document.querySelectorAll('[data-docs-drawer-open]').forEach((b) => b.setAttribute('aria-expanded', String(open)));
      if (open) setTimeout(() => drawer.querySelector('[data-docs-drawer-close]')?.focus(), 50);
    };
    document.querySelectorAll('[data-docs-drawer-open]').forEach((b) => b.addEventListener('click', (e) => { e.stopPropagation(); setDrawer(true); }));
    drawer.querySelectorAll('[data-docs-drawer-close]').forEach((b) => b.addEventListener('click', () => setDrawer(false)));
    document.addEventListener('click', (e) => { if (drawer.classList.contains('is-open') && !drawer.contains(e.target)) setDrawer(false); });
    document.addEventListener('keydown', (e) => { if (e.key === 'Escape') setDrawer(false); });
  }

  /* "on this page": the last heading above 120 px from the top marks its link .is-active */
  document.querySelectorAll('[data-docs-toc]').forEach((toc) => {
    const links = [...toc.querySelectorAll('a[href^="#"]')];
    const targets = links.map((a) => document.getElementById(decodeURIComponent(a.hash.slice(1)))).filter(Boolean);
    if (!targets.length) return;
    let ticking = false;
    const update = () => {
      ticking = false;
      let current = targets[0];
      targets.forEach((t) => { if (t.getBoundingClientRect().top <= 120) current = t; });
      if (innerHeight + scrollY >= document.documentElement.scrollHeight - 4) current = targets[targets.length - 1];
      links.forEach((a) => {
        const on = a.hash.slice(1) === current.id;
        a.classList.toggle('is-active', on);
        if (on) a.setAttribute('aria-current', 'location'); else a.removeAttribute('aria-current');
      });
    };
    addEventListener('scroll', () => { if (!ticking) { ticking = true; requestAnimationFrame(update); } }, { passive: true });
    update();
  });

  /* copy-page split button: [data-docs-copy-toggle] opens the menu (.is-open on [data-docs-copy-menu]) */
  document.querySelectorAll('[data-docs-copy-menu]').forEach((box) => {
    const toggle = box.querySelector('[data-docs-copy-toggle]');
    const set = (open) => { box.classList.toggle('is-open', open); toggle.setAttribute('aria-expanded', String(open)); };
    toggle.addEventListener('click', (e) => { e.stopPropagation(); set(!box.classList.contains('is-open')); });
    document.addEventListener('click', (e) => { if (!box.contains(e.target)) set(false); });
    document.addEventListener('keydown', (e) => { if (e.key === 'Escape') set(false); });
  });

  /* page → Markdown (title + the rich-text flow of [data-prose]) for "Copy page" */
  const pageMarkdown = () => {
    const out = [`# ${(document.querySelector('[data-docs-title]')?.textContent ?? document.title).trim()}`];
    document.querySelector('[data-prose]')?.querySelectorAll(':scope > *').forEach((el) => {
      const text = el.innerText.trim();
      if (el.matches('h2')) out.push(`## ${text}`);
      else if (el.matches('h3')) out.push(`### ${text}`);
      else if (el.matches('ul')) out.push([...el.children].map((li) => `- ${li.innerText.trim()}`).join('\n'));
      else if (el.matches('ol')) out.push([...el.children].map((li, i) => `${i + 1}. ${li.innerText.trim()}`).join('\n'));
      else if (el.querySelector('pre')) out.push(`\`\`\`\n${el.querySelector('pre').innerText.trim()}\n\`\`\``);
      else if (text) out.push(text);
    });
    return `${out.join('\n\n')}\n\nSource: ${pageUrl}\n`;
  };
  document.querySelectorAll('[data-docs-copy-page]').forEach((b) => b.addEventListener('click', async () => {
    if (!(await copyText(pageMarkdown()))) return;
    flash(b.closest('[data-docs-copy-menu]') ?? b);
    const label = b.querySelector('[data-docs-copy-label]');
    if (label) { const was = label.textContent; label.textContent = 'Copied'; setTimeout(() => { label.textContent = was; }, 1600); }
  }));
  document.querySelectorAll('[data-docs-copy-link]').forEach((b) => b.addEventListener('click', async () => {
    if (await copyText(pageUrl)) flash(b);
  }));

  /* code blocks: [data-code-copy] copies its block's <pre> without the prompt glyphs ([data-code-prompt]) */
  document.querySelectorAll('[data-code-copy]').forEach((b) => b.addEventListener('click', async () => {
    const pre = b.closest('[data-code]')?.querySelector('pre');
    if (!pre) return;
    const clone = pre.cloneNode(true);
    clone.querySelectorAll('[data-code-prompt]').forEach((p) => p.remove());
    if (!(await copyText(clone.textContent.trim()))) return;
    flash(b);
    const label = b.querySelector('[data-code-copy-label]');
    if (label) { label.textContent = 'Copied'; setTimeout(() => { label.textContent = 'Copy'; }, 1600); }
  }));

  /* assistant + share links get this page's URL: [data-docs-ai="chatgpt|claude|cursor|gemini|perplexity"]
     (data-docs-ai-mode="summarize" asks for a summary), [data-docs-share="x|facebook|linkedin"] */
  const AI_URL = {
    chatgpt: (q) => `https://chatgpt.com/?q=${q}`,
    claude: (q) => `https://claude.ai/new?q=${q}`,
    gemini: (q) => `https://gemini.google.com/app?q=${q}`,
    perplexity: (q) => `https://www.perplexity.ai/search?q=${q}`,
    cursor: (q) => `cursor://anysphere.cursor-deeplink/prompt?text=${q}`,
  };
  document.querySelectorAll('[data-docs-ai]').forEach((a) => {
    const ask = a.dataset.docsAiMode === 'summarize'
      ? `Summarize this PXpace documentation page: ${pageUrl}`
      : `Read ${pageUrl} so I can ask questions about it.`;
    a.href = AI_URL[a.dataset.docsAi]?.(encodeURIComponent(ask)) ?? a.href;
  });
  const SHARE_URL = {
    x: (u) => `https://x.com/intent/post?url=${u}`,
    facebook: (u) => `https://www.facebook.com/sharer/sharer.php?u=${u}`,
    linkedin: (u) => `https://www.linkedin.com/sharing/share-offsite/?url=${u}`,
  };
  document.querySelectorAll('[data-docs-share]').forEach((a) => { a.href = SHARE_URL[a.dataset.docsShare]?.(encodeURIComponent(pageUrl)) ?? a.href; });
})();
